CREATE TABLE IF NOT EXISTS private.fin_reset_backups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reset_at timestamptz NOT NULL,reset_by uuid NOT NULL,counts jsonb NOT NULL,transactions jsonb NOT NULL,events jsonb NOT NULL,notifications jsonb NOT NULL,push_deliveries jsonb NOT NULL,operation_start jsonb);
REVOKE ALL ON private.fin_reset_backups FROM PUBLIC,anon,authenticated;
ALTER TABLE public.fin_operation_start ADD COLUMN IF NOT EXISTS reset_at timestamptz;
CREATE OR REPLACE FUNCTION private.fin_operation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE ts timestamptz; rs timestamptz; BEGIN PERFORM pg_advisory_xact_lock(741928301); SELECT started_at,reset_at INTO ts,rs FROM public.fin_operation_start WHERE id=true; IF TG_OP='INSERT' AND rs IS NOT NULL AND NEW.source='bank' AND (NEW.transaction_at IS NULL OR NEW.transaction_at<=rs) THEN RETURN NULL; END IF; IF TG_OP='UPDATE' AND OLD.operation_test THEN NEW.operation_test:=true; IF (NEW.status,NEW.claimed_by,NEW.reconciled_by,NEW.customer,NEW.money_type,NEW.ref_code,NEW.note,NEW.info_reason,NEW.cancelled_at,NEW.amount,NEW.received_date,NEW.description) IS DISTINCT FROM (OLD.status,OLD.claimed_by,OLD.reconciled_by,OLD.customer,OLD.money_type,OLD.ref_code,OLD.note,OLD.info_reason,OLD.cancelled_at,OLD.amount,OLD.received_date,OLD.description) THEN RAISE EXCEPTION 'Giao dịch thuộc lịch sử kiểm thử chỉ được xem, không xử lý'; END IF; END IF; IF rs IS NULL AND ts IS NOT NULL AND (NEW.transaction_at IS NULL OR NEW.transaction_at<ts) THEN NEW.operation_test:=true; END IF; IF NEW.operation_test AND NEW.gmf_status IN('pending','sending') THEN IF TG_OP='INSERT' THEN RETURN NULL; ELSIF NEW.gmf_status IS DISTINCT FROM OLD.gmf_status THEN RETURN NULL; END IF; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.fin_reset_preview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT private.fin_super(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được reset dữ liệu Tiền Về'; END IF; RETURN jsonb_build_object('bank',(SELECT count(*) FROM public.bank_transactions WHERE source='bank'),'manual',(SELECT count(*) FROM public.bank_transactions WHERE source<>'bank'),'events',(SELECT count(*) FROM public.bank_transaction_events),'notifications',(SELECT count(*) FROM public.notifications WHERE bank_tx_id IS NOT NULL),'push',(SELECT count(*) FROM public.push_deliveries d JOIN public.notifications n ON n.id=d.notification_id WHERE n.bank_tx_id IS NOT NULL),'reset_at',(SELECT reset_at FROM public.fin_operation_start WHERE id=true),'backups',(SELECT count(*) FROM private.fin_reset_backups)); END; $$;
CREATE OR REPLACE FUNCTION public.fin_reset_execute(_confirm text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE me uuid:=auth.uid(); ts timestamptz; c jsonb; bid uuid; BEGIN IF NOT private.fin_super(me) THEN RAISE EXCEPTION 'Chỉ Super Admin được reset dữ liệu Tiền Về'; END IF; IF _confirm IS DISTINCT FROM 'RESET TIEN VE' THEN RAISE EXCEPTION 'Nhập đúng RESET TIEN VE để xác nhận'; END IF; PERFORM pg_advisory_xact_lock(741928301); LOCK TABLE public.bank_transactions IN SHARE ROW EXCLUSIVE MODE; ts:=clock_timestamp(); c:=jsonb_build_object('transactions',(SELECT count(*) FROM public.bank_transactions),'events',(SELECT count(*) FROM public.bank_transaction_events),'notifications',(SELECT count(*) FROM public.notifications WHERE bank_tx_id IS NOT NULL),'push',(SELECT count(*) FROM public.push_deliveries d JOIN public.notifications n ON n.id=d.notification_id WHERE n.bank_tx_id IS NOT NULL)); INSERT INTO private.fin_reset_backups(reset_at,reset_by,counts,transactions,events,notifications,push_deliveries,operation_start) VALUES(ts,me,c,coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.bank_transactions t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(e)) FROM public.bank_transaction_events e),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(n)) FROM public.notifications n WHERE bank_tx_id IS NOT NULL),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM public.push_deliveries d JOIN public.notifications n ON n.id=d.notification_id WHERE n.bank_tx_id IS NOT NULL),'[]'),(SELECT to_jsonb(s) FROM public.fin_operation_start s)) RETURNING id INTO bid; DELETE FROM public.push_deliveries d USING public.notifications n WHERE n.id=d.notification_id AND n.bank_tx_id IS NOT NULL; DELETE FROM public.notifications WHERE bank_tx_id IS NOT NULL; DELETE FROM public.bank_transaction_events WHERE tx_id IS NOT NULL; DELETE FROM public.bank_transactions WHERE id IS NOT NULL; INSERT INTO public.fin_operation_start(id,started_at,started_by,reset_at) VALUES(true,ts,me,ts) ON CONFLICT(id) DO UPDATE SET started_at=ts,started_by=me,reset_at=ts; RETURN jsonb_build_object('reset_at',ts,'backup_id',bid,'counts',c); END; $$;
CREATE OR REPLACE FUNCTION public.fin_operation_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE s public.fin_operation_start; BEGIN IF NOT private.fin_super(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được xem mốc vận hành Tiền Về'; END IF; SELECT * INTO s FROM public.fin_operation_start WHERE id=true; RETURN jsonb_build_object('started_at',s.started_at,'started_by',s.started_by,'reset_at',s.reset_at); END; $$;
REVOKE ALL ON FUNCTION public.fin_reset_preview() FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.fin_reset_execute(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fin_reset_preview() TO authenticated;
GRANT EXECUTE ON FUNCTION public.fin_reset_execute(text) TO authenticated;